function Button({ children, onClick, variant = 'primary', className = '', type = 'button', disabled = false, testId }: {
  children: ReactNode; onClick?: () => void; variant?: 'primary' | 'outline' | 'ghost' | 'soft'; className?: string; type?: 'button' | 'submit'; disabled?: boolean; testId?: string;
}) {
  const styles = {
    primary: 'bg-[#173744] text-[#fbf7ed] hover:bg-[#285363] shadow-sm',
    outline: 'border border-[#cfc9bb] bg-[#fbf7ed] text-[#173744] hover:border-[#173744] hover:bg-[#f2ecdd]',
    ghost: 'text-[#53646a] hover:bg-[#eae5d9] hover:text-[#173744]',
    soft: 'bg-[#d8ece7] text-[#173744] hover:bg-[#c4e2dc]',
  };
  return <button type={type} onClick={onClick} disabled={disabled} data-testid={testId} className={`inline-flex items-center justify-center gap-2 rounded-[10px] px-4 py-2.5 text-sm font-semibold transition-all duration-200 active:scale-[.98] disabled:cursor-not-allowed disabled:opacity-50 ${styles[variant]} ${className}`}>{children}</button>;
}

function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'mint' | 'amber' | 'coral' | 'ink' }) {
  const tones = { neutral: 'bg-[#eeeae1] text-[#59686a]', mint: 'bg-[#d8ece7] text-[#22655f]', amber: 'bg-[#fff0c9] text-[#8d641f]', coral: 'bg-[#f6ded5] text-[#994d40]', ink: 'bg-[#e0e8e8] text-[#173744]' };
  return <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-bold tracking-[.02em] ${tones[tone]}`}>{children}</span>;
}

function Field({ label, value, onChange, placeholder, area = false }: { label: string; value: string; onChange: (v: string) => void; placeholder?: string; area?: boolean }) {
  return <label className="block space-y-1.5"><span className="text-[11px] font-bold uppercase tracking-[.12em] text-[#718083]">{label}</span>
    {area ? <textarea value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} data-testid={`input-${label.toLowerCase().replaceAll(' ', '-')}`} className="min-h-[108px] w-full resize-none rounded-[10px] border border-[#d5cfc2] bg-[#fcfaf3] px-3.5 py-3 text-sm text-[#173744] outline-none transition focus:border-[#47958d] focus:ring-2 focus:ring-[#47958d]/15" /> :
      <input value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} data-testid={`input-${label.toLowerCase().replaceAll(' ', '-')}`} className="h-11 w-full rounded-[10px] border border-[#d5cfc2] bg-[#fcfaf3] px-3.5 text-sm text-[#173744] outline-none transition focus:border-[#47958d] focus:ring-2 focus:ring-[#47958d]/15" />}
  </label>;
}

